parameters.functionCode:
// Califnco Catalog Rotator
// Selects the next scheduled product for daily spotlight
const catalog = [
  {
    "id": "cal-001",
    "name": "Califnco AquaShield RO+UV+UF+Alkaline Purifier",
    "category": "RO Water Purifiers",
    "features": ["10-Stage Purification", "Copper Boost Alkaline", "Digital TDS Display", "10L Stainless Steel Tank"],
    "mrp": 16999,
    "wholesalePrice": 10899,
    "targetAudience": "Homeowners & Health-conscious families",
    "imagePrompt": "Ultra realistic commercial advertisement photo of Califnco premium domestic RO water purifier mounted on modern luxury kitchen wall, crystal clear water stream pouring into transparent glass, clean lighting, 8k resolution, minimalist design"
  },
  {
    "id": "cal-002",
    "name": "Califnco CopperGuard Active Copper Mineral RO",
    "category": "RO Water Purifiers",
    "features": ["Infused Active Copper", "Micro-filtration UV", "Auto-Flush Solenoid", "Zero Water Waste Tech"],
    "mrp": 18499,
    "wholesalePrice": 11999,
    "targetAudience": "Families seeking Ayurvedic copper wellness and pure hydration",
    "imagePrompt": "Commercial studio product photography of Califnco copper water purifier with rose-gold metallic accents, condensation drops on pure glass pitcher, sparkling mineral water, studio softbox lighting, photorealistic"
  },
  {
    "id": "cal-003",
    "name": "Califnco PureDrive 100 GPD Heavy Flow Booster Pump",
    "category": "Booster Pumps & Motors",
    "features": ["100 GPD Heavy Flow", "36V High Torque DC Motor", "Ultra-Quiet SilentVibe Technology", "CE & RoHS Certified"],
    "mrp": 2499,
    "wholesalePrice": 1550,
    "targetAudience": "Plumbers, technicians, and water purifier dealers",
    "imagePrompt": "Industrial product shot of heavy duty water purifier booster pump motor, 100 GPD label, precision engineered brass fittings, clean white studio background, high contrast lighting, engineering catalog quality"
  },
  {
    "id": "cal-004",
    "name": "Califnco Commercial 50 LPH Heavy Duty RO Plant",
    "category": "Commercial & Industrial RO",
    "features": ["50 Litres Per Hour", "Stainless Steel 304 Skid Frame", "Dual 4040 Membrane", "Digital Flow & TDS Controller"],
    "mrp": 45000,
    "wholesalePrice": 32000,
    "targetAudience": "Offices, schools, clinics, and industrial cafeterias",
    "imagePrompt": "Professional photograph of Califnco 50 LPH stainless steel skid commercial RO plant, dual blue pressure vessels, digital pressure gauges, industrial kitchen setup, sharp focus, hyper-realistic"
  }
];

// Pick product based on current day of year
const dayOfYear = Math.floor((new Date() - new Date(new Date().getFullYear(), 0, 0)) / 1000 / 60 / 60 / 24);
const product = catalog[dayOfYear % catalog.length];

return [{ json: { ...product, scheduledDate: new Date().toISOString() } }];

